using System; using System.IO; using System.Linq; using System.Collections.Generic; class Program { static void Main() { var lines = File.ReadLines(@"e:\Project\CapacityModelingSimulator\relationDB.txt").Skip(1); var tables = new HashSet<string>(); foreach(var line in lines) { var parts = line.Split('\t'); if (parts.Length >= 7) { tables.Add(parts[0]); tables.Add(parts[6]); } } string[] keywords = { "product", "process", "machine", "employee", "shift", "demand", "capacity", "cycletime", "group", "route" }; foreach(var kw in keywords) { var matches = tables.Where(t => t != null && t.IndexOf(kw, StringComparison.OrdinalIgnoreCase) >= 0).OrderBy(t => t.Length).ToList(); Console.WriteLine($"Keyword '{kw}' ({matches.Count} tables):"); foreach(var m in matches) Console.WriteLine("  " + m); } } }
